// Merge and deduplicate items from Notion and Linear
// Transform to standardized PARA format

const allItems = [];
const seenIds = new Set();

// Process Notion items
function processNotionItem(item, stage) {
  const id = `notion_${item.id}`;
  if (seenIds.has(id)) return null;

  seenIds.add(id);

  // Extract properties from Notion page
  const properties = item.properties || {};

  return {
    external_id: item.id,
    source: 'notion',
    title: properties.Name?.title?.[0]?.plain_text || item.title || 'Untitled',
    content: item.content || '',
    stage: stage,
    urgency: properties.Urgency?.select?.name?.toLowerCase() || 'medium',
    importance: properties.Importance?.select?.name?.toLowerCase() || 'medium',
    due_date: properties['Due Date']?.date?.start || null,
    estimated_duration: properties['Estimated Duration']?.number || null,
    blocks_others: properties['Blocks Others']?.checkbox || false,
    affected_areas: properties['Affected Areas']?.multi_select?.map(s => s.name) || [],
    tags: properties.Tags?.multi_select?.map(s => s.name) || [],
    last_opened: item.last_edited_time,
    notion_database_id: item.database_id,
    metadata: {
      notion_url: item.url,
      created_time: item.created_time,
      last_edited_time: item.last_edited_time
    }
  };
}

// Process Linear items
function processLinearItem(item) {
  const id = `linear_${item.id}`;
  if (seenIds.has(id)) return null;

  seenIds.add(id);

  // Map Linear state to PARA stage
  let stage = 'tasks'; // default
  const stateName = item.state?.name?.toLowerCase() || '';
  if (stateName.includes('backlog') || stateName.includes('todo')) stage = 'jots';
  else if (stateName.includes('in progress') || stateName.includes('started')) stage = 'tasks';
  else if (stateName.includes('done') || stateName.includes('completed')) stage = 'archives';

  // Map priority to urgency/importance
  let urgency = 'medium';
  let importance = 'medium';
  const priority = item.priority || 0;
  if (priority >= 3) {
    urgency = 'urgent';
    importance = 'high';
  } else if (priority >= 2) {
    importance = 'high';
  }

  return {
    external_id: item.id,
    source: 'linear',
    title: item.title,
    content: item.description || '',
    stage: stage,
    urgency: urgency,
    importance: importance,
    due_date: item.dueDate || null,
    estimated_duration: null, // Linear doesn't have this
    blocks_others: false, // Default
    affected_areas: [],
    tags: item.labels?.map(l => l.name) || [],
    last_opened: item.updatedAt,
    linear_project_id: item.project?.id || null,
    metadata: {
      linear_url: item.url,
      state: item.state?.name,
      priority: item.priority,
      assignee: item.assignee?.name,
      created_at: item.createdAt,
      updated_at: item.updatedAt
    }
  };
}

// Process all inputs
$input.all().forEach(input => {
  if (input.json && Array.isArray(input.json.results)) {
    // Notion response
    const stage = input.json.database_name?.toLowerCase().includes('jot') ? 'jots' :
                  input.json.database_name?.toLowerCase().includes('task') ? 'tasks' :
                  input.json.database_name?.toLowerCase().includes('project') ? 'projects' : 'tasks';

    input.json.results.forEach(item => {
      const processed = processNotionItem(item, stage);
      if (processed) allItems.push(processed);
    });
  } else if (input.json && Array.isArray(input.json)) {
    // Linear response
    input.json.forEach(item => {
      const processed = processLinearItem(item);
      if (processed) allItems.push(processed);
    });
  }
});

return allItems;

// Log ingestion summary
console.log(`Ingested ${$input.all().length} items from Notion and Linear`);

return {
  ingested_count: $input.all().length,
  timestamp: new Date().toISOString(),
  sources: ['notion', 'linear'],
  stages_processed: ['jots', 'tasks', 'projects']
};
